import{r as e}from"./auth-bgkSYldb.js";var t={list(t=0,n=20){return e.get(`/workspaces/current/subscriber-lists`,{params:{page:t,size:n}})},get(t){return e.get(`/workspaces/current/subscriber-lists/${t}`)},create(t){return e.post(`/workspaces/current/subscriber-lists`,t)},update(t,n){return e.put(`/workspaces/current/subscriber-lists/${t}`,n)},delete(t){return e.delete(`/workspaces/current/subscriber-lists/${t}`)},listMembers(t,n=0,r=20){return e.get(`/workspaces/current/subscriber-lists/${t}/members`,{params:{page:n,size:r}})},addMember(t,n){return e.post(`/workspaces/current/subscriber-lists/${t}/members`,{subscriber_id:n})},removeMember(t,n){return e.delete(`/workspaces/current/subscriber-lists/${t}/members`,{data:{subscriber_id:n}})},previewSegment(t){return e.post(`/workspaces/current/subscriber-lists/preview`,{filter_rules:t})}};export{t};